import type { ShotId } from "@content/site";
import { cx } from "@thoth/ui";

/**
 * A real app screenshot (generated by apps/web/e2e/site-shots.ts), in the visitor's theme:
 * the dark capture when the system is dark, the light one otherwise.
 */
export function Shot({
  id,
  alt,
  className,
  priority = false,
}: {
  id: ShotId;
  alt: string;
  className?: string;
  priority?: boolean;
}) {
  return (
    <picture>
      <source srcSet={`/shots/${id}-dark.png`} media="(prefers-color-scheme: dark)" />
      <img
        src={`/shots/${id}-light.png`}
        alt={alt}
        width={1440}
        height={900}
        loading={priority ? "eager" : "lazy"}
        decoding="async"
        className={cx(
          "block h-auto w-full rounded-lg border border-border-subtle bg-surface-200 shadow-hearth-lg",
          className,
        )}
      />
    </picture>
  );
}
